#include <esp_sleep.h>

const int LDR_PIN = 0;           // GPIO0
const uint64_t SLEEP_TIME = 60;  // seconds

RTC_DATA_ATTR uint32_t sampleCount = 0;

void setup()
{
  Serial.begin(115200);
  delay(1000);

  sampleCount++;

  int adcValue = analogRead(LDR_PIN);

  float voltage = (adcValue * 3.3) / 4095.0;

  Serial.println("================================");
  Serial.print("Sample #: ");
  Serial.println(sampleCount);

  Serial.print("ADC Value: ");
  Serial.println(adcValue);

  Serial.print("Voltage: ");
  Serial.print(voltage, 3);
  Serial.println(" V");

  Serial.println("Sleeping for 60 seconds...");
  Serial.println("================================");

  esp_sleep_enable_timer_wakeup(SLEEP_TIME * 1000000ULL);

  Serial.flush();

  esp_deep_sleep_start();
}

void loop()
{
}
